def log_filter(data):
    errors, warnings, infos = [], [], 0
    for line in data.splitlines():
        low = line.lower()
        if any(s in low for s in ('error', 'fatal', 'critical')):
            errors.append(line)
        elif any(s in low for s in ('warn', 'deprecated')):
            warnings.append(line)
        elif 'info' in low:
            infos += 1
    ec, wc = collections.Counter(errors), collections.Counter(warnings)
    out = ['Log Summary', f'   [error] {len(errors)} errors ({len(ec)} unique)',
           f'   [warn] {len(warnings)} warnings ({len(wc)} unique)',
           f'   [info] {infos} info messages', '']
    if errors:
        out.append('[ERRORS]')
        for line, n in ec.items():
            out.append(f'   [×{n}] {line}' if n > 1 else f'   {line}')
        out.append('')
    if warnings:
        out.append('[WARNINGS]')
        for line, n in wc.items():
            out.append(f'   [×{n}] {line}' if n > 1 else f'   {line}')
        out.append('')
    return '\n'.join(out).rstrip() + '\n'


